when HTTP_REQUEST {
  if { [HTTP::uri] ends_with "cgi" } {
     pool cgi_pool
  } elseif { [HTTP::uri] starts_with "/abc" } {
     pool abc_servers
 }
}

# Make uri path start with /prefix if it doesn't already
when HTTP_REQUEST {
  if { not ([HTTP::uri] starts_with "/prefix") } {
    HTTP::uri /prefix[HTTP::uri]
  }
}
